import{_ as s,o as e,c as n,ag as p}from"./chunks/framework.DlQ8ZhpE.js";const f=JSON.parse('{"title":"流量与请求限速","description":"","frontmatter":{"title":"流量与请求限速","order":2},"headers":[],"relativePath":"zhHans/docs/features/rate-limiting.md","filePath":"zhHans/docs/features/rate-limiting.md"}'),i={name:"zhHans/docs/features/rate-limiting.md"};function t(c,a,l,o,r,d){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="流量与请求限速" tabindex="-1">流量与请求限速 <a class="header-anchor" href="#流量与请求限速" aria-label="Permalink to &quot;流量与请求限速&quot;">​</a></h1><p>Pavonis 支持两类限速：流量限速（控制带宽）和请求频率限速（控制 QPS）。各项限速均为可选。字段与配置示例见 <a href="./../config/resource-limit"><code>ResourceLimitConfig</code></a>。</p><p>限速分为两个层级：</p><ul><li>每客户端：流量限速与请求频率限速按客户端分别计算，每个客户端拥有独立的额度</li><li>全局：流量可额外设置所有客户端合计的总上限</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 ──► 客户端请求频率（秒/分/时） ── 超限 ──► 429</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼ 放行</span></span>
<span class="line"><span>数据 ──► 客户端流量桶 ──► 全局流量桶 ──► 传输</span></span>
<span class="line"><span>         （令牌不足时等待，即降速，不拒绝）</span></span></code></pre></div><p>一个请求需要同时满足所有已配置的限制。限速作用于所有代理类站点，<a href="./../sites/speed-test">测速</a>站点除外。</p><h2 id="客户端的划分" tabindex="-1">客户端的划分 <a class="header-anchor" href="#客户端的划分" aria-label="Permalink to &quot;客户端的划分&quot;">​</a></h2><p>客户端按来源 IP 划分：IPv4 按单个地址，IPv6 按所在的 <code>/64</code> 网段。同一 <code>/64</code> 网段内的 IPv6 地址共享同一份额度。</p><p>位于反向代理之后时，客户端 IP 取决于 <a href="./../config/server"><code>server</code></a> 中受信任代理的配置。</p><h2 id="流量限速" tabindex="-1">流量限速 <a class="header-anchor" href="#流量限速" aria-label="Permalink to &quot;流量限速&quot;">​</a></h2><p>使用令牌桶算法控制流量速率：桶以 <code>traffic_avg_mibps</code> 的速率持续填充令牌，每传输 1 MiB 数据消耗 1 个令牌。空闲时积累的令牌（最多 <code>traffic_burst_mib</code> 个）允许短时间内超过平均速率。<code>traffic_max_mibps</code> 则限制峰值速率。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>           traffic_avg_mibps（持续补充）</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>           ┌─────────────┐</span></span>
<span class="line"><span>           │ ● ● ● ● ●   │  容量 traffic_burst_mib</span></span>
<span class="line"><span>           │ ● ● ● ● ●   │  空闲时攒满，可短时突发</span></span>
<span class="line"><span>           └──────┬──────┘</span></span>
<span class="line"><span>                  │ 每 1 MiB 取走 1 个令牌</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>       传输速率 ≤ traffic_max_mibps</span></span></code></pre></div><p>流量超限时传输会等待令牌，表现为降速，不会中断或拒绝请求。</p><p>流量按上传与下载合计计算。全局流量限速的 <code>global_traffic_*</code> 字段与之一一对应，作用于所有客户端的流量总和，适用于控制服务器总带宽。</p><h2 id="请求频率限速" tabindex="-1">请求频率限速 <a class="header-anchor" href="#请求频率限速" aria-label="Permalink to &quot;请求频率限速&quot;">​</a></h2><p>按客户端限制请求数量，秒、分钟、小时三个粒度可同时生效。任一条件超限时，请求将被拒绝并返回 <code>429 Too Many Requests</code>。</p>`,16)])])}const _=s(i,[["render",t]]);export{f as __pageData,_ as default};
